/// The class a bare call to `function` must be emitted as a
/// `callstatic` on, or `None` when no class declares it `global`.
pub fn global_class(function: &str) -> Option<&'static str> {
    let n = function.to_ascii_lowercase();
    GLOBALS.iter().find(|(f, _)| *f == n).map(|(_, c)| *c)
}

/// Every class that declares at least one `global` function.
///
/// A dotted call on one of these — `Sound.StopInstance(x)` — is a
/// `callstatic`, not a `callmethod` on a variable called `sound`. The
/// caller must still check that the name is not a property or local of
/// its own: `Sound Property sfx auto` makes `sfx.Play(...)` a call on the
/// instance.
pub const GLOBAL_CLASSES: &[&str] = &[
    "custom",
    "cwscript",
    "debug",
    "dunyngolglowattracttrig",
    "game",
    "imagespacemodifier",
    "math",
    "message",
    "rpdefault_math",
    "rpdefault_utility",
    "screenshot",
    "sound",
    "survival_globalfunctions",
    "utility",
    "weather",
];

/// Whether `class` declares any `global` function.
pub fn is_global_class(class: &str) -> bool {
    let n = class.to_ascii_lowercase();
    GLOBAL_CLASSES.iter().any(|c| *c == n)
}
